    """Return earliest arrival tick at shelter for a single person, or None."""
    sr, sc = person["r"], person["c"]
    release = person["release"]
    tr, tc = shelter["r"], shelter["c"]
    if not _safe(request, fire, sr, sc, release):
        return None
    h = len(request["grid"])
    w = len(request["grid"][0])
    best = {}
    queue = [(release, sr, sc)]
    best[(sr, sc)] = release
    while queue:
        t, r, c = heapq.heappop(queue)
        if best.get((r, c)) != t:
            continue
        if t > request["max_ticks"]:
            continue
        for nr, nc in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
            nt = t + 1
            if nt > request["max_ticks"]:
                continue
            if not _safe(request, fire, nr, nc, nt):
                continue
            if nt < best.get((nr, nc), float("inf")):
                best[(nr, nc)] = nt
